def shout(fn):
    def wrapper(*args):
        return fn(*args).upper()
    return wrapper
@shout
def greet(name):
    return f"hi {name}"
print(greet("ana"))

def deco(fn):
    def wrapper(*a, **k):
        return fn(*a, **k)
    return wrapper
@deco
def add(a, b):
    return a + b
print(add.__name__)

def tag(t):
    def deco(fn):
        def wrapper():
            return f"<{t}>{fn()}</{t}>"
        return wrapper
    return deco
@tag("b")
@tag("i")
def word():
    return "hi"
print(word())

from functools import lru_cache
calls = 0
@lru_cache(maxsize=None)
def fib(n):
    global calls
    calls += 1
    return n if n < 2 else fib(n - 1) + fib(n - 2)
fib(10)
print(calls)
